function blankState(){return {
  name:'',group:'',session:'',startedAt:null,finishedAt:null,current:0,completed:[],scores:[0,0,0,0,0],
  m1:{cursor:0,tries:{},points:{}},m2:{tries:{},points:{}},
  m3:{phase:0,order:['S304','S301','S306','S303','S305','S302'],tries:{},points:{}},
  m4:{phase:0,blocks:[],tries:{},points:{},generated:'',critique:JSON.stringify(FLAWED,null,2),genFeedback:null,critFeedback:null,genFallback:false,critFallback:false},
  m5:{cursor:0,tries:{},points:{},slider:{0:20,1:19}}
};}
function loadState(){try{const str=localStorage.getItem(STORAGE_KEY);if(!str)return blankState();const obj=JSON.parse(str);if(!obj || typeof obj.name!=='string' || !Array.isArray(obj.scores) || obj.scores.length!==5 || !obj.m1 || !obj.m2 || !obj.m3 || !obj.m4 || !obj.m5)return blankState();return obj;}catch{return blankState();}}
let s=loadState();
const ui={reveal:null,archiveSelected:null,dragID:null,feedback:null,helpOn:false};
const $ = selector => document.querySelector(selector);
function esc(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function store(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(s));}catch{toast('La sauvegarde locale est indisponible sur ce navigateur.');}}
function total(){return s.scores.reduce((a,b)=>a+Number(b||0),0);}
function nDone(i){return Object.keys(s['m'+(i+1)]?.points||{}).length;}
function pointsFor(max,errors){return errors===0?max:errors===1?Math.ceil(max/2):0;}
function recordPoints(i,key,pts){const m=s['m'+(i+1)];if(Object.prototype.hasOwnProperty.call(m.points,key))return; m.points[key]=pts;s.scores[i]=Math.min(20,Object.values(m.points).reduce((a,b)=>a+b,0));store();}
function stageAttempt(i,key,correct,max,explanation){const m=s['m'+(i+1)];let errors=m.tries[key]||0;if(Object.prototype.hasOwnProperty.call(m.points,key))return true;if(correct){const pts=pointsFor(max,errors);recordPoints(i,key,pts);ui.reveal={i,key,title:pts>0?'✅ Diagnostic confirmé':'✅ Solution obtenue',detail:explanation,pts};return true;}errors++;m.tries[key]=errors;store();if(errors>=3){recordPoints(i,key,0);ui.reveal={i,key,title:'🔎 Solution révélée',detail:explanation,pts:0};return true;}ui.feedback={i,kind:'bad',title:errors===1?'Première tentative : indice':'Deuxième tentative : explication',detail:errors===1?'Vérifie les seuils et distingue une valeur égale à la limite d’une valeur qui la dépasse.':explanation};return false;}
function toast(text){const box=$('#toast');box.textContent=text;box.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>box.classList.remove('show'),2700);}
function uid(){return 'ARES-'+Date.now().toString(36).toUpperCase()+'-'+Math.floor(Math.random()*1e5).toString(36).toUpperCase();}
function setStageFinished(i){if(!s.completed.includes(i)){s.completed.push(i);store();toast('🏆 Mission '+(i+1)+' terminée !');launchConfetti();}}
function launchConfetti(){
  if(typeof window.matchMedia==='function'&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const colors=['#68e9ff','#ffca6d','#68e3b2','#ff925f','#b4a4ff'];
  for(let j=0;j<26;j++){
    const particle=document.createElement('span');
    particle.className='mission-confetti';
    particle.style.left=(15+Math.random()*70)+'vw';
    particle.style.top=(10+Math.random()*28)+'vh';
    particle.style.background=colors[j%colors.length];
    particle.style.setProperty('--dx',(Math.random()*220-110)+'px');
    particle.style.setProperty('--dy',(150+Math.random()*240)+'px');
    particle.style.animationDelay=(Math.random()*.25)+'s';
    document.body.appendChild(particle);
    setTimeout(()=>particle.remove(),1600);
  }
}
function rank(){const pts=total();return pts>=90?'Commandant des données':pts>=70?'Ingénieur ARES-7':pts>=50?'Analyste orbital':'Explorateur martien';}
function statusOf(r){if(!r||['temperature','oxygen','radiation','battery'].some(k=>typeof r[k]!=='number'||!Number.isFinite(r[k])))return 'invalid';if(r.oxygen<0||r.oxygen>100||r.battery<0||r.battery>100||r.radiation<0)return 'invalid';return r.temperature<THRESHOLDS.temperatureMin||r.temperature>THRESHOLDS.temperatureMax||r.oxygen<THRESHOLDS.oxygenMin||r.radiation>THRESHOLDS.radiationMax||r.battery<THRESHOLDS.batteryMin?'alert':'stable';}
function dateValid(str){if(typeof str!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(str))return false;let dt=new Date(str+'T00:00:00Z');return Number.isFinite(dt.getTime())&&dt.toISOString().slice(0,10)===str;}
function validateData(text,kind){let data;const issues=[];const fail=msg=>{if(issues.length<18)issues.push(msg);};let info={n:0,stable:0,alerts:0,boundaries:0};if(typeof text!=='string'||text.length>250000)return {ok:false,issues:['Le JSON est vide ou dépasse 250 000 caractères.'],info};try{data=JSON.parse(text);}catch(e){return {ok:false,issues:['Syntaxe JSON invalide : '+e.message],info};}if(!data||typeof data!=='object'||Array.isArray(data))return {ok:false,issues:['La racine doit être un objet JSON.'],info};if(!data.mission||typeof data.mission.name!=='string'||!data.mission.name.trim())fail('mission.name doit contenir un nom.');if(!Array.isArray(data.crew)||data.crew.length<1)fail('crew doit être un tableau avec au moins un membre fictif.');else if(data.crew.some(x=>!x||typeof x.id!=='string'||!x.id||typeof x.name!=='string'||typeof x.role!=='string'))fail('Chaque membre de crew doit contenir id, name et role (textes).');if(!Array.isArray(data.readings))return {ok:false,issues:[...issues,'readings doit être un tableau de relevés.'],info};const r=data.readings;info.n=r.length;if(r.length>(kind==='gen'?80:100))fail('Le jeu contient trop de relevés (maximum 80 pour la Forge).');if(kind==='gen'&&r.length<10)fail('Il faut au moins 10 relevés pour la génération.');if(kind==='critique'&&r.length!==8)fail('La correction doit contenir exactement 8 relevés.');const ids=new Set(),sols=new Set(),alertSensors=new Set(),boundarySensors=new Set();let prevSol=-Infinity,prevDate='';r.forEach((x,i)=>{if(!x||typeof x!=='object'||Array.isArray(x)){fail(`Relevé ${i+1} : objet attendu.`);return;}const loc=`Relevé ${i+1}`;if(typeof x.id!=='string'||!x.id.trim())fail(loc+' : id manquant ou non textuel.');else if(ids.has(x.id))fail(loc+` : id en doublon (${x.id}).`);else ids.add(x.id);if(!Number.isInteger(x.sol)||x.sol<1)fail(loc+' : sol doit être un entier positif.');else if(sols.has(x.sol))fail(loc+` : sol en doublon (${x.sol}).`);else sols.add(x.sol);if(!dateValid(x.date))fail(loc+' : date invalide (attendu YYYY-MM-DD).');if(kind==='critique'){if(Number.isInteger(x.sol)&&x.sol<=prevSol)fail(loc+' : les Sols ne sont pas dans l’ordre croissant.');if(dateValid(x.date)&&prevDate&&x.date<=prevDate)fail(loc+' : dates non croissantes.');if(Number.isInteger(x.sol))prevSol=x.sol;if(dateValid(x.date))prevDate=x.date;}
for(const key of ['temperature','oxygen','radiation','battery'])if(typeof x[key]!=='number'||!Number.isFinite(x[key]))fail(loc+` : ${key} doit être un nombre non nul et fini.`);if(typeof x.oxygen==='number'&&(x.oxygen<0||x.oxygen>100))fail(loc+' : oxygen doit être compris entre 0 et 100.');if(typeof x.battery==='number'&&(x.battery<0||x.battery>100))fail(loc+' : battery doit être compris entre 0 et 100.');if(typeof x.radiation==='number'&&x.radiation<0)fail(loc+' : radiation doit être positive ou nulle.');const st=statusOf(x);if(st==='stable')info.stable++;if(st==='alert'){info.alerts++;if(x.temperature< -70||x.temperature>20)alertSensors.add('temperature');if(x.oxygen<18)alertSensors.add('oxygen');if(x.radiation>5)alertSensors.add('radiation');if(x.battery<20)alertSensors.add('battery');}if(x.temperature===-70||x.temperature===20)boundarySensors.add('temperature');if(x.oxygen===18)boundarySensors.add('oxygen');if(x.radiation===5)boundarySensors.add('radiation');if(x.battery===20)boundarySensors.add('battery');});info.boundaries=boundarySensors.size;
if(kind==='gen'){if(info.stable<2)fail('Il faut au moins deux relevés STABLES.');if(info.alerts<4)fail('Il faut au moins quatre relevés en ALERTE.');for(const sensor of ['temperature','oxygen','radiation','battery'])if(!alertSensors.has(sensor))fail(`Aucune alerte provoquée par le capteur ${sensor}.`);if(boundarySensors.size<2)fail('Il faut des valeurs exactement sur au moins deux seuils de capteurs différents.');}
if(kind==='critique'){const expected=Array.from({length:8},(_,i)=>'Q'+String(i+1).padStart(2,'0'));for(const id of expected)if(!ids.has(id))fail('Identifiant attendu manquant : '+id+'.');for(let i=0;i<r.length;i++)if(Number.isInteger(r[i]?.sol)&&r[i].sol!==601+i)fail(`Le Sol attendu pour ${r[i].id||'la ligne '+(i+1)} est ${601+i}.`);if(info.stable<2)fail('Il faut au moins deux relevés STABLES.');if(info.alerts<2)fail('Il faut au moins deux relevés en ALERTE.');if(boundarySensors.size<1)fail('Il faut au moins une valeur exactement sur un seuil.');}
return {ok:issues.length===0,issues,info,data};}
function scoreLines(){return MISSIONS.map((m,i)=>({name:m.title,points:s.scores[i],done:s.completed.includes(i)}));}
function fmtDate(ts){return new Date(ts).toLocaleString('fr-CA',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function duration(){if(!s.startedAt)return 0;return Math.max(1,Math.round(((s.finishedAt||Date.now())-s.startedAt)/60000));}
function missionTop(i,progress,totalRounds){return `<div class="mission-top"><div class="mission-kicker"><span>${String(i+1).padStart(2,'0')}</span><div>MISSION ${i+1} / 5 · ${esc(MISSIONS[i].title.toUpperCase())}</div></div><div class="btn-row"><span class="score-tag">⭐ ${s.scores[i]} / 20 pts</span>${typeof progress==='number'?`<div class="rounds" aria-label="Avancement du défi">${Array.from({length:totalRounds},(_,x)=>`<i class="${x<progress?'done':x===progress?'active':''}"></i>`).join('')}</div>`:''}</div></div>`;}
function lyra(msg){return `<div class="lyra"><div class="lyra-face">🤖</div><div><strong>LYRA — ASSISTANTE DE BORD</strong><p>${msg}</p></div></div>`;}
function showFeedback(i){if(!ui.feedback||ui.feedback.i!==i)return '';return `<div class="feedback ${ui.feedback.kind==='bad'?'bad':''}"><h3>${esc(ui.feedback.title)}</h3><p>${esc(ui.feedback.detail)}</p></div>`;}
function revealBlock(){if(!ui.reveal)return '';return `<div class="feedback"><h3>${esc(ui.reveal.title)} ${ui.reveal.pts?`+${ui.reveal.pts} points`:''}</h3><p>${esc(ui.reveal.detail)}</p><button class="btn primary" data-action="next-reveal">Continuer →</button></div>`;}
function renderSidebar(){const unlocked=Math.min(4,s.completed.length);$('#missionList').innerHTML=MISSIONS.map((m,i)=>`<button class="nav-mission ${s.current===i?'active':''} ${s.completed.includes(i)?'completed':''}" ${!s.name||i>unlocked?'disabled':''} data-action="nav" data-index="${i}"><span class="num">${s.completed.includes(i)?'✓':i+1}</span><span><span class="label">${m.icon} ${esc(m.title)}</span><span class="desc">${esc(m.desc)}</span></span>${i>unlocked?'<span class="lock">🔒</span>':''}</button>`).join('');$('#sideCount').textContent=s.completed.length+' / 5';$('#sidePct').textContent=(s.completed.length*20)+'%';$('#sideBar').style.width=(s.completed.length*20)+'%';$('#topScore').textContent=total();$('#topXP').textContent=total()*10;$('#systemStatus').textContent=!s.name?'SYSTÈME EN ATTENTE':s.completed.length===5?'MISSION ACCOMPLIE':'LIAISON ARES-7 ACTIVE';}
function render(){renderSidebar();const main=$('#main');if(!s.name)main.innerHTML=renderIntro();else if(s.current===5)main.innerHTML=renderReport();else if(s.completed.includes(s.current))main.innerHTML=renderMissionFinish(s.current);else main.innerHTML=[renderDiagnostic,renderArchives,renderChrono,renderForge,renderSabotage][s.current]();}
function renderIntro(){return `<div class="eyebrow">TRANSMISSION PRIORITAIRE // MARS 2042</div><h1 class="hero-heading">La mission ARES-7 a besoin <strong>de toi.</strong></h1><p class="subhead">Une tempête de données perturbe les instruments de l'habitat. Deviens analyste de mission : classe, vérifie et répare les jeux de données avant qu'il ne soit trop tard !</p><div class="intro-art" role="img" aria-label="Vue stylisée de l'habitat martien et de Mars"><span class="art-label">HABITAT MARTIEN — LIAISON ÉTABLIE</span><span class="station">⌂</span></div>${lyra('Bienvenue, recrue ! Cinq missions t’attendent. Aucun code à écrire : tout se fait à bord, sauf les deux demandes à ton IA externe.')}<div class="grid-two"><div class="card-panel"><h2>🎯 Ta feuille de route</h2><p>5 missions · 100 points possibles · environ 30 minutes sans limite de temps. Chaque mission débloque la suivante.</p><div class="grid-two"><div class="minor-stat"><strong>5</strong><small>Missions</small></div><div class="minor-stat"><strong>100</strong><small>Points possibles</small></div></div></div><div class="card-panel glow"><h2>🧑‍🚀 Identification</h2><form id="startForm"><label class="input-line">Nom de l'étudiant <input id="studentName" required maxlength="70" autocomplete="name" placeholder="Prénom et nom"></label><div class="gap"></div><label class="input-line">Groupe <input id="studentGroup" required maxlength="50" placeholder="Ex. : 420-5Y5"></label><div class="gap"></div><button class="btn primary" type="submit">🚀 Lancer la mission ARES-7</button></form><p class="fine" style="margin-top:12px">La progression est sauvegardée uniquement dans ce navigateur.</p></div></div><div class="info-note">🛡️ Règles de sécurité : température [−70, 20] °C ; oxygène ≥ 18 % ; radiation ≤ 5 mSv ; batterie ≥ 20 %. Les bornes sont inclusives.</div>`;}
function metricCard(spec,r){const v=r[spec.key],bad=statusOf(r)==='invalid'?false:(spec.key==='temperature'?(v< -70||v>20):spec.key==='oxygen'?v<18:spec.key==='radiation'?v>5:v<20);const w=Math.max(0,Math.min(100,((v-spec.min)/(spec.max-spec.min))*100));return `<div class="metric-card ${bad?'bad':''}"><div class="metric-head"><span>${spec.icon} ${spec.label}</span><strong>${v} ${spec.unit}</strong></div><div class="meter ${bad?'danger':''}"><span style="width:${w}%"></span></div><span class="threshold">Normal : ${spec.norm}</span></div>`;}
function renderDiagnostic(){const m=s.m1;let i=m.cursor;if(i>=DIAGNOSTIC.length){setStageFinished(0);return renderMissionFinish(0);}const r=DIAGNOSTIC[i],status=statusOf(r);const expl=status==='stable'?'Tous les capteurs respectent leurs seuils, y compris les valeurs exactement sur les bornes.':'Au moins un seuil est franchi : '+SENSOR_SPECS.filter(spec=>spec.key==='temperature'?(r.temperature< -70||r.temperature>20):spec.key==='oxygen'?r.oxygen<18:spec.key==='radiation'?r.radiation>5:r.battery<20).map(x=>x.label).join(', ')+'.';return `${missionTop(0,i,5)}<h1>📡 Diagnostic martien</h1><p class="subhead">Analyse les capteurs de l'habitat et détermine s'il est STABLE ou en ALERTE.</p>${lyra('Un seul capteur hors des seuils suffit pour déclencher une ALERTE. Attention : une valeur exactement sur sa borne autorisée reste STABLE.')}<div class="card-panel glow"><div class="title-line"><div><div class="eyebrow">TRANSMISSION ${i+1} / 5</div><h2>Relevé ${r.id} · Sol ${r.sol}</h2><p>${r.date}</p></div><span class="chip orange">${m.tries['r'+i]||0} erreur(s)</span></div><div class="grid-four">${SENSOR_SPECS.map(spec=>metricCard(spec,r)).join('')}</div>${ui.reveal?revealBlock():`<div class="option-grid"><button class="option" data-action="diagnostic" data-value="stable">🟢 CONDITIONS STABLES</button><button class="option" data-action="diagnostic" data-value="alert">🔴 ALERTE</button></div>${showFeedback(0)}`}<p class="fine">Une bonne réponse au premier essai vaut 4 points. Les indices diminuent progressivement les points.</p></div>`;}
function renderArchives(){const m=s.m2,done=Object.keys(m.points),current=ARCHIVE.filter(x=>!done.includes(x.id));if(!current.length){setStageFinished(1);return renderMissionFinish(1);}return `${missionTop(1,done.length,7)}<h1>📦 Archives stellaires</h1><p class="subhead">Classe les situations dans la bonne famille de jeux de données. Glisse une carte dans un secteur ou sélectionne une carte, puis un secteur.</p>${lyra('Pour la mission, les étiquettes servent à identifier l’usage principal des données. Certaines données pourraient appartenir à plusieurs catégories en réalité.')}<div class="card-panel"><div class="title-line"><h2>📥 Cartes à trier</h2><span class="chip">${done.length} / 7 classées</span></div><div class="deck-grid">${ARCHIVE.map(a=>`<div tabindex="0" role="button" aria-pressed="${ui.archiveSelected===a.id}" draggable="${!done.includes(a.id)}" class="deck-card ${done.includes(a.id)?'done':''} ${ui.archiveSelected===a.id?'selected':''}" data-archive-card="${a.id}"><div class="deck-num">${done.includes(a.id)?'✓ CLASSÉ':'DOSSIER '+a.id.toUpperCase()}</div><p>${esc(a.label)}</p></div>`).join('')}</div></div><div class="card-panel"><h2>🗂️ Secteurs de rangement</h2><div class="bucket-grid">${BUCKETS.map(b=>`<button class="bucket" data-action="bucket" data-bucket="${b.id}">${b.label}<small>${esc(b.tip)}</small></button>`).join('')}</div><p class="fine" style="margin-top:13px">Carte sélectionnée : <strong>${esc(ARCHIVE.find(x=>x.id===ui.archiveSelected)?.label||'clique une carte')}</strong>. Chaque carte vaut jusqu'à 3 points (la dernière : 2).</p>${showFeedback(1)}</div>`;}
function renderChrono(){const m=s.m3;if(m.phase>=3){setStageFinished(2);return renderMissionFinish(2);}const phase=m.phase;return `${missionTop(2,phase,3)}<h1>⏱️ Chrono-Sol</h1><p class="subhead">Le journal de mission a été mélangé. Rétablis l'ordre des Sols pour identifier les premières anomalies.</p>${lyra(phase===0?'Replace les six relevés dans l’ordre chronologique. Tu peux les glisser-déposer ou utiliser les flèches.':'Un jeu temporel permet de lire une évolution, pas seulement des valeurs isolées.')}<div class="card-panel glow"><div class="title-line"><div><span class="eyebrow">${phase===0?'PHASE 1 · RECONSTRUCTION':'PHASE '+(phase+1)+' · ANALYSE'}</span><h2>${phase===0?'Réorganise le journal de bord':'Lis les tendances'}</h2></div><span class="score-tag">${phase===0?'12 pts':'4 pts'}</span></div>${phase===0?renderChronoSort():renderChronoQuiz(phase-1)}${ui.reveal?revealBlock():showFeedback(2)}</div>`;}
function renderChronoSort(){const m=s.m3;return `<div aria-label="Chronologie à réorganiser">${m.order.map((id,i)=>{const x=CHRONO.find(x=>x.id===id);return `<div class="timeline-item" draggable="true" data-time-card="${x.id}"><span class="ordered-index">${i+1}.</span><span class="time-id">Sol ${x.sol}</span><span class="time-detail">${x.date}<br>O₂ ${x.oxygen}% · ☢ ${x.radiation} mSv · 🔋 ${x.battery}%</span><span class="move-buttons"><button aria-label="Monter le Sol ${x.sol}" data-action="move-time" data-from="${i}" data-dir="-1" ${i===0?'disabled':''}>↑</button><button aria-label="Descendre le Sol ${x.sol}" data-action="move-time" data-from="${i}" data-dir="1" ${i===m.order.length-1?'disabled':''}>↓</button></span></div>`;}).join('')}</div>${!ui.reveal?'<div class="btn-row"><button class="btn primary" data-action="check-order">🔎 Vérifier l’ordre</button><span class="fine">Dépose aussi une ligne sur une autre pour changer sa position.</span></div>':''}`;}
function renderTrendChart(){
  const pts=CHRONO.map((x,i)=>({x:40+i*104,y:21+(22-x.oxygen)*18,sol:x.sol,oxygen:x.oxygen}));
  const poly=pts.map(p=>`${p.x},${p.y}`).join(' ');
  const threshold=21+(22-18)*18;
  return `<div class="trend-graph" role="img" aria-label="Courbe de l'oxygène en baisse de 21 à 16 pour cent du Sol 301 au Sol 306, seuil minimum 18 pour cent"><svg viewBox="0 0 600 164" xmlns="http://www.w3.org/2000/svg"><line x1="26" y1="${threshold}" x2="580" y2="${threshold}" stroke="#ff8b83" stroke-dasharray="6 6" stroke-width="2"/><text x="576" y="${threshold-8}" font-size="11" fill="#ffb29e" text-anchor="end">SEUIL 18 %</text><polyline points="${poly}" fill="none" stroke="#6ae9fa" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round"/>${pts.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5.5" fill="${p.oxygen<18?'#ff7089':'#75f0e4'}"/><text x="${p.x}" y="${p.y-12}" text-anchor="middle" font-size="11" fill="#e6f5ff">${p.oxygen}%</text><text x="${p.x}" y="155" text-anchor="middle" font-size="11" fill="#99bfd5">${p.sol}</text>`).join('')}</svg></div>`;
}
function renderChronoQuiz(index){const q=CHRONO_QUIZ[index];return `${renderTrendChart()}<div class="info-note">Oxygène : 21 → 20 → 19 → 18 → 17 → 16 %.<br>Radiation : 2 → 2,4 → 3 → 4 → 4,6 → 5,3 mSv.<br>Batterie : 90 → 85 → 79 → 68 → 55 → 43 %.</div><h3>${esc(q.question)}</h3>${!ui.reveal?`<div class="option-grid">${q.answers.map(([v,label])=>`<button class="option" data-action="chrono-answer" data-value="${v}">${esc(label)}</button>`).join('')}</div>`:''}`;}
function renderForge(){const m=s.m4;if(m.phase>=3){setStageFinished(3);return renderMissionFinish(3);}const titles=['Assembler le prompt','Produire les données','Corriger les anomalies'];return `${missionTop(3,m.phase,3)}<h1>🤖 Forge de données IA</h1><p class="subhead">Deux défis avec ton IA externe. Tout se valide ici : copie le prompt, utilise l'IA dans un autre onglet, colle le JSON dans CosmoLab.</p>${lyra(m.phase===0?'Un bon prompt décrit le contexte, les règles, la couverture et le format. Assemble ces quatre blocs dans un ordre logique.':m.phase===1?'Fais produire un jeu de données à ton IA. CosmoLab contrôle réellement la structure, les seuils et la diversité des scénarios.':'Le jeu de données a été saboté : demande une critique à ton IA, puis colle la version corrigée pour vérification.')}<div class="card-panel glow"><div class="title-line"><div><span class="eyebrow">FORGE IA · ÉTAPE ${m.phase+1} / 3</span><h2>${titles[m.phase]}</h2></div><span class="score-tag">${[4,10,6][m.phase]} pts</span></div>${m.phase===0?renderPromptBuilder():m.phase===1?renderJSONStage('gen'):renderJSONStage('critique')}</div>`;}
function renderPromptBuilder(){const m=s.m4;return `<p>Choisis les composants d'un prompt dans l'ordre attendu. Tu pourras ensuite le copier pour l'envoyer à une IA.</p><div class="prompt-workshop"><div><h3>Blocs disponibles</h3><div class="prompt-pieces">${PROMPT_BLOCKS.map(b=>`<button class="prompt-piece" data-action="add-block" data-key="${b.key}" ${m.blocks.includes(b.key)?'disabled':''}>${b.title}</button>`).join('')}</div></div><div><h3>Ton prompt (${m.blocks.length} / 4)</h3><div class="prompt-assembly">${m.blocks.length?m.blocks.map((key,i)=>`<div class="prompt-slot"><span>${i+1}. ${PROMPT_BLOCKS.find(x=>x.key===key).title}</span><button data-action="remove-block" data-key="${key}" aria-label="Retirer ce bloc">×</button></div>`).join(''):'<p>Ajoute des blocs pour construire le prompt.</p>'}</div></div></div><div class="gap"></div><button class="btn primary" data-action="check-prompt" ${ui.reveal?'disabled':''}>Vérifier la structure du prompt</button>${ui.reveal?revealBlock():showFeedback(3)}<p class="fine">Ordre recommandé : décrire le besoin, préciser les règles, définir les scénarios, puis imposer le format.</p>`;}
function renderJSONStage(kind){const m=s.m4,isGen=kind==='gen',title=isGen?'Prompt de génération':'Prompt de critique',prompt=isGen?PROMPT_BLOCKS.map(b=>b.content).join('\n\n'):PROMPT_CRITIQUE,feedback=isGen?m.genFeedback:m.critFeedback;return `<p>${isGen?'Le JSON doit couvrir au moins 10 relevés, deux STABLES, quatre types d’alertes et deux seuils exactement atteints.':'Le jeu saboté présente six anomalies à corriger. Le résultat doit conserver huit relevés cohérents et chronologiques.'}</p><div class="title-line"><h3>📋 ${title}</h3><button class="btn small" data-action="copy-prompt" data-kind="${kind}">⧉ Copier le prompt</button></div><pre class="prompt-container">${esc(prompt)}</pre>${!isGen?`<div class="btn-row" style="margin:12px 0"><button class="btn small" data-action="copy-flawed">⧉ Copier les données sabotées</button><span class="fine">Ajoute-les après le prompt dans ton IA.</span></div>`:''}<h3>🧪 ${isGen?'JSON généré':'JSON corrigé'} — colle-le ci-dessous</h3><textarea class="json-editor" id="${isGen?'genEditor':'critEditor'}" spellcheck="false" aria-label="Éditeur JSON ${isGen?'généré':'corrigé'}" placeholder="Colle ici uniquement le JSON, sans blocs Markdown...">${esc(isGen?m.generated:m.critique)}</textarea><div class="btn-row" style="margin-top:12px"><button class="btn primary" data-action="validate-json" data-kind="${kind}">🛡️ Analyser le JSON</button><label class="btn small ghost">📂 Importer un .json <input hidden type="file" accept=".json,application/json" data-file="${kind}"></label><button class="btn small ghost" data-action="fallback-json" data-kind="${kind}">🛟 Jeu de secours (points réduits)</button></div>${feedback?`<div class="validation-box ${feedback.ok?'good':'bad'}"><strong>${feedback.ok?'✅ Jeu conforme':'⚠️ Vérification : corrections à effectuer'}</strong><div class="validator-stats"><span>Relevés : ${feedback.info.n}</span><span>STABLES : ${feedback.info.stable}</span><span>ALERTES : ${feedback.info.alerts}</span><span>Seuils représentés : ${feedback.info.boundaries}</span></div>${feedback.issues.length?`<ul>${feedback.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p class="fine" style="margin:10px 0 0">La structure, les données et la couverture attendue sont valides.</p>'}</div>`:''}${ui.reveal?revealBlock():''}<p class="fine">Contrôle local uniquement. Ne colle aucune donnée personnelle réelle dans une IA externe. ${isGen?'La génération IA est notée selon sa conformité, non selon la quantité de texte produit.':'Une correction indépendante est nécessaire : les commentaires de l’IA ne prouvent pas la validité du JSON.'}</p>`;}
function renderSabotage(){const m=s.m5,i=m.cursor;if(i>=SABOTAGE.length){setStageFinished(4);return renderMissionFinish(4);}const q=SABOTAGE[i],slider=m.slider[i]??q.start;return `${missionTop(4,i,5)}<h1>☢️ Sabotage des données</h1><p class="subhead">Le système reçoit des valeurs suspectes. Identifie le problème ou répare la mesure, avant la panne générale.</p>${lyra('Un relevé incomplet n’est pas automatiquement stable ! Sépare une valeur hors des seuils d’une donnée qui ne respecte même pas le schéma.')}<div class="card-panel glow"><div class="title-line"><div><span class="eyebrow">INCIDENT ${i+1} / 5</span><h2>${esc(q.label)}</h2></div><span class="chip orange">+4 pts possibles</span></div><div class="info-note orange">${esc(q.desc)}</div>${q.kind==='slider'?`<div class="range-wrap"><div class="range-value ${i===0&&slider>20?'danger':''}" id="rangeLabel">${slider} ${q.unit}</div><input type="range" min="${q.min}" max="${q.max}" step="${q.step}" value="${slider}" id="sabotageRange" aria-label="Régler ${esc(q.label)}"><div class="range-labels"><span>${q.min} ${q.unit}</span><span>${q.max} ${q.unit}</span></div></div>${!ui.reveal?'<div class="btn-row" style="margin-top:15px"><button class="btn primary" data-action="sabotage-check">✅ Confirmer le réglage</button></div>':''}`:!ui.reveal?`<div class="option-grid">${q.options.map(([v,label])=>`<button class="option" data-action="sabotage-answer" data-value="${v}">${esc(label)}</button>`).join('')}</div>`:''}${ui.reveal?revealBlock():showFeedback(4)}</div>`;}
function renderMissionFinish(i){const m=MISSIONS[i];return `${missionTop(i)}<div class="card-panel mission-finish glow"><div class="trophy">🏆</div><div class="eyebrow">MISSION ${i+1} TERMINÉE</div><h1>${esc(m.title)}</h1><p>Les systèmes martiens reconnaissent ton intervention. ${i<4?'Le prochain secteur est maintenant accessible.':'Tu as sécurisé ARES-7 et terminé les cinq missions.'}</p><div class="big-number">${s.scores[i]} / 20</div><p>Points obtenus dans cette mission</p><div class="btn-row" style="justify-content:center"><button class="btn primary" data-action="next-mission">${i<4?'Débloquer la mission '+(i+2)+' →':'🏁 Voir mon rapport final'}</button></div></div><div class="badge-panel" style="margin-top:15px"><h3>🎖️ Badge déverrouillé</h3><span class="badge-card">${m.icon} ${esc(m.short)} • ARES-7</span></div>`;}
function reportTable(){return scoreLines().map((x,i)=>`<tr><td>${i+1}. ${esc(x.name)}</td><td>${x.done?'Terminée':'En cours'}</td><td><strong>${x.points} / 20</strong></td></tr>`).join('');}
function renderReport(){const done=s.completed.length===5,date=s.finishedAt||Date.now();return `<div class="no-print report-title"><div class="eyebrow">TRANSMISSION FINALE // ARES-7</div><h1>🏆 Rapport de mission</h1><p class="subhead">La mission est terminée. Imprime ce tableau de bord pour remettre la preuve de ta progression pédagogique.</p></div><div class="print-sheet" id="printReport"><div class="report-heading"><div><div style="font-weight:900;letter-spacing:.14em;color:#126d8d">◈ COSMOLAB · ARES-7</div><h2 style="margin:4px 0">RAPPORT FINAL DE MISSION</h2><span style="font-size:.8rem">Jeux de données — Mission Mars 2.0</span></div><div style="font-size:2.2rem">🚀</div></div><p><strong>Étudiant :</strong> ${esc(s.name)} &nbsp;&nbsp; <strong>Groupe :</strong> ${esc(s.group)}<br><strong>Session :</strong> ${esc(s.session)}<br><strong>Date de fin :</strong> ${esc(fmtDate(date))} &nbsp;&nbsp; <strong>Durée :</strong> ${duration()} min</p><div class="report-stats"><div><strong>${total()}/100</strong><small>Score obtenu</small></div><div><strong>${s.completed.length}/5</strong><small>Missions terminées</small></div><div><strong>${total()*10}</strong><small>XP accumulés</small></div></div><h3 style="margin:18px 0 5px">${done?'✅ MISSION COMPLÉTÉE':'MISSION NON TERMINÉE'}</h3><p style="margin:0"><strong>Rang obtenu :</strong> ${rank()}</p><table><thead><tr><th>Mission</th><th>Statut</th><th>Pointage</th></tr></thead><tbody>${reportTable()}<tr><th>TOTAL</th><th>${s.completed.length} / 5</th><th>${total()} / 100</th></tr></tbody></table><h3 style="margin:18px 0 5px">Maîtrise des concepts</h3><table><thead><tr><th>Compétence</th><th>Progression</th></tr></thead><tbody>${['Seuils et classification','Catégories de jeux de données','Chronologie et cohérence','Génération et validation IA','Limites et données invalides'].map((x,i)=>`<tr><td>${esc(x)}</td><td>${s.scores[i]} / 20 — ${s.scores[i]>=14?'Maîtrisé':s.scores[i]>=8?'En progression':'À renforcer'}</td></tr>`).join('')}</tbody></table><h3 style="margin:18px 0 5px">Badges de mission</h3><p style="margin:0;font-size:.82rem">${s.completed.map(i=>MISSIONS[i].icon+' '+esc(MISSIONS[i].short)).join(' · ')}</p><div class="report-footer">CosmoLab ARES-7 • Rapport généré localement à partir des activités réalisées sur ce navigateur. La mention « Mission complétée » confirme la progression dans le jeu, sans certifier à elle seule l'identité ou l'utilisation d'une IA externe. ${s.m4.genFallback||s.m4.critFallback?'Mode secours utilisé dans la Forge IA.':''}</div></div><div class="card-panel no-print report-actions"><div class="btn-row"><button class="btn primary" data-action="print">🖨️ Imprimer / Enregistrer en PDF</button><button class="btn ghost" data-action="reset">↻ Rejouer (réinitialise les résultats)</button></div><p class="fine">Pour un PDF : choisir « Enregistrer au format PDF » comme imprimante dans Chrome ou Edge.</p></div>`;}

function nextReveal(){if(!ui.reveal)return;const i=ui.reveal.i;ui.reveal=null;ui.feedback=null;if(i===0){s.m1.cursor++;if(s.m1.cursor>=DIAGNOSTIC.length)setStageFinished(0);}else if(i===2){s.m3.phase++;if(s.m3.phase>=3)setStageFinished(2);}else if(i===3){s.m4.phase++;if(s.m4.phase>=3)setStageFinished(3);}else if(i===4){s.m5.cursor++;if(s.m5.cursor>=SABOTAGE.length)setStageFinished(4);}store();render();}
function processArchive(target){if(s.current!==1||s.completed.includes(1))return;const item=ARCHIVE.find(x=>x.id===ui.archiveSelected);if(!item){toast('Choisis d’abord une carte à trier.');return;}const m=s.m2;if(Object.prototype.hasOwnProperty.call(m.points,item.id))return;let errs=m.tries[item.id]||0;const max=item.id==='g'?2:3;if(item.type===target){const awarded=pointsFor(max,errs);recordPoints(1,item.id,awarded);ui.feedback={i:1,kind:'good',title:`✅ ${item.label} — +${awarded} pts`,detail:item.explain};ui.archiveSelected=null;}else{errs++;m.tries[item.id]=errs;if(errs>=3){recordPoints(1,item.id,0);ui.feedback={i:1,kind:'bad',title:'🔎 Carte reclassée automatiquement',detail:item.explain};ui.archiveSelected=null;}else{ui.feedback={i:1,kind:'bad',title:errs===1?'Mauvais secteur — essaie encore':'Dernier indice avant la solution',detail:errs===1?'Pense à la raison principale pour laquelle ce jeu de données serait préparé.':item.explain};}}if(Object.keys(m.points).length===ARCHIVE.length)setStageFinished(1);store();render();}
function moveTimeline(from,to){if(s.current!==2||s.m3.phase!==0||ui.reveal)return;const arr=s.m3.order;if(from<0||to<0||from>=arr.length||to>=arr.length||from===to)return;const [moving]=arr.splice(from,1);arr.splice(to,0,moving);ui.feedback=null;store();render();}
function checkTimeline(){const correct=s.m3.order.every((id,i)=>id===CHRONO[i].id);const resolved=stageAttempt(2,'order',correct,12,'La série doit aller du Sol 301 au Sol 306, dans le même ordre que les dates du 1er au 6 août 2042.');if(resolved&&!correct)s.m3.order=CHRONO.map(x=>x.id);store();render();}
function handleJSONValidation(kind){const m=s.m4,isGen=kind==='gen',field=isGen?'generated':'critique';const editor=$('#'+(isGen?'genEditor':'critEditor'));if(!editor)return;m[field]=editor.value;const result=validateData(editor.value,kind);if(isGen)m.genFeedback={ok:result.ok,issues:result.issues,info:result.info};else m.critFeedback={ok:result.ok,issues:result.issues,info:result.info};if(result.ok){const key=isGen?'gen':'crit';if(!Object.prototype.hasOwnProperty.call(m.points,key)){const tries=m.tries[key]||0;const pts=isGen?(m.genFallback?2:tries===0?10:tries===1?7:tries===2?5:3):(m.critFallback?0:tries===0?6:tries===1?4:tries===2?2:1);recordPoints(3,key,pts);ui.reveal={i:3,key,title:isGen?'✅ Génération validée':'✅ Données réparées',detail:isGen?'Le jeu couvre les alertes de quatre capteurs, les cas stables et les valeurs frontières.':'Les types, identifiants, valeurs et relations temporelles sont maintenant conformes.',pts};}}else{m.tries[isGen?'gen':'crit']=(m.tries[isGen?'gen':'crit']||0)+1;}store();render();}
function handleJSONFallback(kind){const m=s.m4;const isGen=kind==='gen';if(!confirm('Utiliser un jeu de secours ? Cette option permet de terminer le défi, mais réduit les points possibles.'))return;if(isGen){m.generated=JSON.stringify(GENERATED_EXAMPLE,null,2);m.genFallback=true;}else{m.critique=JSON.stringify(CORRECTED_CRITIQUE,null,2);m.critFallback=true;}store();render();toast('Jeu de secours chargé. Clique sur « Analyser le JSON ».');}
function copyText(text){const copyFallback=()=>{const a=document.createElement('textarea');a.value=text;a.style.position='fixed';a.style.opacity='0';document.body.append(a);a.select();let ok=false;try{ok=document.execCommand('copy');}catch{}a.remove();if(!ok)toast('Sélectionne le texte du prompt, puis utilise Ctrl+C.');else toast('📋 Copié ! Ouvre ton IA dans un autre onglet.');};if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(text).then(()=>toast('📋 Copié ! Ouvre ton IA dans un autre onglet.'),copyFallback);}else copyFallback();}
function actions(action,b){switch(action){
  case 'nav':{const idx=Number(b.dataset.index);if(s.name&&idx<=s.completed.length&&idx<5){ui.reveal=null;ui.feedback=null;ui.archiveSelected=null;s.current=idx;store();render();}break;}
  case 'next-mission':{const next=s.current+1;s.current=next;if(next>=5&&!s.finishedAt)s.finishedAt=Date.now();ui.feedback=null;ui.reveal=null;store();render();break;}
  case 'diagnostic':{if(ui.reveal)return;const i=s.m1.cursor,r=DIAGNOSTIC[i],expected=statusOf(r),choice=b.dataset.value;const detail=expected==='stable'?'Toutes les valeurs sont conformes. Les bornes -70 °C, 20 °C, 18 %, 5 mSv et 20 % sont incluses.':'Au moins un capteur a franchi sa limite : '+SENSOR_SPECS.filter(spec=>spec.key==='temperature'?(r.temperature< -70||r.temperature>20):spec.key==='oxygen'?r.oxygen<18:spec.key==='radiation'?r.radiation>5:r.battery<20).map(x=>x.label).join(', ')+'.';stageAttempt(0,'r'+i,choice===expected,4,detail);render();break;}
  case 'bucket':processArchive(b.dataset.bucket);break;
  case 'move-time':moveTimeline(Number(b.dataset.from),Number(b.dataset.from)+Number(b.dataset.dir));break;
  case 'check-order':if(!ui.reveal)checkTimeline();break;
  case 'chrono-answer':{if(ui.reveal)return;const q=CHRONO_QUIZ[s.m3.phase-1];stageAttempt(2,q.key,b.dataset.value===q.correct,4,q.reason);render();break;}
  case 'add-block':{const arr=s.m4.blocks;if(!arr.includes(b.dataset.key))arr.push(b.dataset.key);ui.feedback=null;store();render();break;}
  case 'remove-block':{s.m4.blocks=s.m4.blocks.filter(x=>x!==b.dataset.key);ui.feedback=null;store();render();break;}
  case 'check-prompt':{if(ui.reveal)return;const good=s.m4.blocks.join(',')===PROMPT_BLOCKS.map(x=>x.key).join(',');const resolved=stageAttempt(3,'prompt',good,4,'Ordre logique : Contexte → Règles → Couverture → Format. Les instructions doivent préciser les contraintes et ce que le JSON doit couvrir.');if(resolved&&!good)s.m4.blocks=PROMPT_BLOCKS.map(x=>x.key);store();render();break;}
  case 'copy-prompt':{const gen=b.dataset.kind==='gen';const prompt=gen?PROMPT_BLOCKS.map(x=>x.content).join('\n\n'):PROMPT_CRITIQUE+'\n\nJSON saboté à corriger :\n'+JSON.stringify(FLAWED,null,2);copyText(prompt);break;}
  case 'copy-flawed':copyText(JSON.stringify(FLAWED,null,2));break;
  case 'validate-json':if(!ui.reveal)handleJSONValidation(b.dataset.kind);break;
  case 'fallback-json':if(!ui.reveal)handleJSONFallback(b.dataset.kind);break;
  case 'sabotage-check':{if(ui.reveal)return;const m=s.m5,q=SABOTAGE[m.cursor];stageAttempt(4,'s'+m.cursor,Math.abs(Number(m.slider[m.cursor]??q.start)-q.correct)<1e-8,4,q.reason);render();break;}
  case 'sabotage-answer':{if(ui.reveal)return;const m=s.m5,q=SABOTAGE[m.cursor];stageAttempt(4,'s'+m.cursor,b.dataset.value===q.correct,4,q.reason);render();break;}
  case 'next-reveal':nextReveal();break;
  case 'print':window.print();break;
  case 'reset':resetGame();break;
}}
function resetGame(){if(!confirm('Recommencer ? Les résultats de cette session seront définitivement effacés sur ce navigateur.'))return;try{localStorage.removeItem(STORAGE_KEY);}catch{}s=blankState();ui.reveal=null;ui.feedback=null;ui.archiveSelected=null;render();toast('Nouvelle session prête.');}
function initialize(){render();const main=$('#main');main.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button){actions(button.dataset.action,button);return;}const card=event.target.closest('[data-archive-card]');if(card){const id=card.dataset.archiveCard;if(!Object.prototype.hasOwnProperty.call(s.m2.points,id)){ui.archiveSelected=id;ui.feedback=null;render();}}});$('#missionList').addEventListener('click',event=>{const btn=event.target.closest('[data-action]');if(btn)actions(btn.dataset.action,btn);});
  main.addEventListener('submit',e=>{if(e.target.id!=='startForm')return;e.preventDefault();const name=$('#studentName').value.trim(),group=$('#studentGroup').value.trim();if(!name||!group){toast('Entre ton nom et ton groupe.');return;}s.name=name;s.group=group;s.session=uid();s.startedAt=Date.now();s.current=0;store();render();});
  main.addEventListener('input',event=>{const target=event.target;if(target.id==='sabotageRange'){const current=s.m5.cursor;s.m5.slider[current]=Number(target.value);const out=$('#rangeLabel');if(out){out.textContent=target.value+' '+SABOTAGE[current].unit;out.classList.toggle('danger',current===0&&Number(target.value)>20);}store();}if(target.id==='genEditor'){s.m4.generated=target.value;store();}if(target.id==='critEditor'){s.m4.critique=target.value;store();}});
  main.addEventListener('change',event=>{const input=event.target.closest('[data-file]');if(!input||!input.files?.length)return;const file=input.files[0];if(file.size>250000){toast('Fichier trop volumineux (250 Ko maximum).');return;}const kind=input.dataset.file;const reader=new FileReader();reader.onload=()=>{if(kind==='gen')s.m4.generated=String(reader.result);else s.m4.critique=String(reader.result);store();render();toast('Fichier chargé. Analyse-le pour vérifier les données.');};reader.onerror=()=>toast('Impossible de lire le fichier.');reader.readAsText(file);});
  main.addEventListener('keydown',event=>{const card=event.target.closest('[data-archive-card]');if(card&&(event.key==='Enter'||event.key===' ')){event.preventDefault();card.click();}});
  main.addEventListener('dragstart',event=>{const archive=event.target.closest('[data-archive-card]');if(archive&&!Object.prototype.hasOwnProperty.call(s.m2.points,archive.dataset.archiveCard)){ui.dragID=archive.dataset.archiveCard;ui.archiveSelected=ui.dragID;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',ui.dragID);return;}const timeline=event.target.closest('[data-time-card]');if(timeline){ui.dragID=timeline.dataset.timeCard;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',ui.dragID);}});
  main.addEventListener('dragover',event=>{const target=event.target.closest('.bucket,[data-time-card]');if(!target)return;event.preventDefault();event.dataTransfer.dropEffect='move';if(target.classList.contains('bucket'))target.classList.add('over');});
  main.addEventListener('dragleave',event=>{const target=event.target.closest('.bucket');if(target)target.classList.remove('over');});
  main.addEventListener('drop',event=>{const bucket=event.target.closest('.bucket');if(bucket){event.preventDefault();bucket.classList.remove('over');if(ui.dragID&&ARCHIVE.some(x=>x.id===ui.dragID)){ui.archiveSelected=ui.dragID;processArchive(bucket.dataset.bucket);}ui.dragID=null;return;}const row=event.target.closest('[data-time-card]');if(row&&s.current===2&&s.m3.phase===0){event.preventDefault();const from=s.m3.order.indexOf(ui.dragID),to=s.m3.order.indexOf(row.dataset.timeCard);moveTimeline(from,to);ui.dragID=null;}});
  $('#resetBtn').addEventListener('click',resetGame);$('#helpButton').addEventListener('click',()=>$('#helpModal').classList.remove('hidden'));$('#closeHelp').addEventListener('click',()=>$('#helpModal').classList.add('hidden'));$('#helpOkay').addEventListener('click',()=>$('#helpModal').classList.add('hidden'));$('#helpModal').addEventListener('click',e=>{if(e.target.id==='helpModal')e.currentTarget.classList.add('hidden');});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#helpModal').classList.add('hidden');});
}
document.addEventListener('DOMContentLoaded',initialize);
